  c = mix(c, vec3(0.62, 0.88, 0.76), smoothstep(0.52, 0.75, n2) * 0.85);
  c = mix(c, vec3(0.98, 0.90, 0.62), smoothstep(0.58, 0.8, 1.0 - n2) * 0.6);
